  }

  {
    const response = await fastify.inject('/plugin2/bar')
    t.assert.strictEqual(response.body, 'tata')
  }

  {
    const response = await fastify.inject('/plugin2/plugin3/foo')
    t.assert.strictEqual(response.body, 'toto')
  }

